pub const D86_Y_MIN: f64 = 1.0 / 40.0;
pub const D86_Y_MAX: f64 = 39.0 / 40.0;

const D86_HALF: [f64; 20] = [
    7.736, 25.158, 43.302, 59.693, 73.920, 86.112, 96.523, 105.407, 112.986, 119.447, 124.942,
    129.596, 133.508, 136.760, 139.416, 141.525, 143.128, 144.253, 144.921, 145.142,
];

/// Canonical WU31-A1 D86 length-gauge representative.
/// Reflect y -> 1-y, then linearly interpolate the printed j/40 half-grid.
/// Outside [1/40,39/40] is UNKNOWN and therefore a typed error, never zero.
pub fn d86_w(y: f64) -> Result<f64, CoverageError> {
    if !y.is_finite() {
        return Err(CoverageError::InvalidInput("two-photon y must be finite"));
    }
    if !(D86_Y_MIN..=D86_Y_MAX).contains(&y) {
        return Err(CoverageError::OutOfBand {
            family: "D86_TABLE_V_LENGTH_LINEAR_B",
            value: y,
            min: D86_Y_MIN,
            max: D86_Y_MAX,
        });
    }
    let yr = if y > 0.5 { 1.0 - y } else { y };
    let x = yr * 40.0;
    let nearest = x.round();
    if (x - nearest).abs() <= 16.0 * f64::EPSILON * x.abs().max(1.0) {
        let idx = nearest as usize;
        if (1..=20).contains(&idx) {
            return Ok(D86_HALF[idx - 1]);
        }
    }
    let j0 = x.floor() as usize;
    let j1 = j0 + 1;
    if j0 < 1 || j1 > 20 {
        return Err(CoverageError::OutOfBand {
            family: "D86_TABLE_V_LENGTH_LINEAR_B",
            value: y,
            min: D86_Y_MIN,
            max: D86_Y_MAX,
        });
    }
    let t = x - j0 as f64;
    Ok(D86_HALF[j0 - 1] * (1.0 - t) + D86_HALF[j1 - 1] * t)
}

pub fn he_two_photon_pair_source(
    y: f64,
    state: &SourceState,
    f1: Mat2,
    f2: Mat2,
) -> Result<TwoPhotonPairOutput, CoverageError> {
    state.validate()?;
    if !f1.is_hermitian(1e-12) || !f2.is_hermitian(1e-12) {
        return Err(CoverageError::InvalidInput("pair F must be Hermitian"));
    }
    let w = d86_w(y)?;
    let h1 = Mat2::identity() + f1;
    let h2 = Mat2::identity() + f2;
    // Identity real screen adapter T12 for fixed-input parity. General transport may
    // supply a rotated screen before calling this source.
    let emit = anticommutator2(h1, h2.transpose()).scale(0.5 * state.ns);
    let absorb = anticommutator2(f1, f2.transpose()).scale(0.5 * state.ng);
    let m = emit - absorb;
    let g = 3.0 / (64.0 * PI * PI);
    let atomic_event_weight = 0.5 * w * g;
    let photon_marginal_weight = w * g;
    Ok(TwoPhotonPairOutput {
        pair_matrix: m,
        event_rate_density: atomic_event_weight * m.trace().re,
        photon_tags_per_event: 2,
        atom_pair_factor: 0.5,
        w_s_inv: w,
        atomic_event_weight_s_inv: atomic_event_weight,
        photon_marginal_weight_s_inv: photon_marginal_weight,
    })
}

