}

fn event_ledger_conserves_nuclei_charge_photons_and_energy() {
    let rates = ChannelRates {
        r584: 2.0,
        rir: -3.0,
        rp: 5.0,
        rs: -7.0,
        r2g: 11.0,
    };
    let e = HeEnergies::canonical();
    let h_kin = -8.0;
    let bf_photon = e.chi_p * rates.rp + e.chi_s * rates.rs + h_kin;
    let l = assemble_he_event_ledger(rates, e, bf_photon, h_kin).unwrap();
    assert!(l.he_nuclei_residual.abs() < 1e-12);
    assert!(l.charge_minus_e_residual.abs() < 1e-12);
    assert!((l.photon_number_source - (2.0 - 3.0 - 5.0 + 7.0 + 22.0)).abs() < 1e-12);
    assert!((l.p_internal + l.p_gamma + l.h_kin).abs() < 1e-10);
    assert_eq!(l.event_matrix[5][4], 2);
}

fn validate_bf(&self) -> Result<(), CoverageError> {
    self.validate()?;
    if self.electron_frame != ElectronFramePolicy::CommonMaterialMaxwell {
        return Err(CoverageError::MissingAuthority {
            family: "BOUND_FREE_SPECIES_DRIFT",
            value: 0.0,
            detail: "inverse kernel is authorized only for common material/electron frame with isotropic nondegenerate Maxwell electrons",
        });
    }
    Ok(())
}

def close(a: float, b: float, tol: float) -> bool:
    return abs(a-b) <= tol * (1.0 + abs(a) + abs(b))

def main() -> int:
    cfg = json.loads(FIXTURE.read_text())
    tol = float(cfg["implementation_tolerance"])
    proc = subprocess.run(
        ["cargo", "run", "--manifest-path", str(MANIFEST), "--locked", "--example", "eval_fixture", "--quiet"],
        cwd=ROOT, text=True, capture_output=True
    )
    if proc.returncode != 0:
        print(proc.stdout, end="")
        print(proc.stderr, end="", file=sys.stderr)
        fail(f"Rust fixture exited {proc.returncode}")
    try:
        got = json.loads(proc.stdout.strip())
    except Exception as exc:
        fail(f"fixture JSON parse: {exc}; stdout={proc.stdout!r}")
    for key, expected in cfg["expected"].items():
        actual = got.get(key)
        if actual is None or not close(float(actual), float(expected), tol):
            fail(f"{key}: got {actual}, expected {expected}, tol={tol}")
    for key in cfg["zero_or_scaled_residual_keys"]:
        value = float(got.get(key, math.inf))
        # Absolute zero-ledger entries are also safely bounded by this same tiny gate.
        if not math.isfinite(value) or abs(value) > tol:
            fail(f"{key}: residual {value} exceeds {tol}")
    if not close(float(got["bb_jvp_num"]), float(got["bb_jvp_ana"]), tol):
        fail(f"BB JVP: numeric {got['bb_jvp_num']} analytic {got['bb_jvp_ana']}")
    print(json.dumps({"status":"PASS","tolerance":tol,"values":got}, sort_keys=True))

fn complex_wp_f_trace_parity_is_preserved() {
    let mut state =
        SourceState::simple(2.0, 0.7, wp_diag(0.4, 0.7, 1.1), 0.3, 0.4, 9000.0).unwrap();
    state.f = Mat2([[c(0.2, 0.0), c(0.03, 0.04)], [c(0.03, -0.04), c(0.1, 0.0)]]);
    state.wp[0][1] = c(0.05, 0.02);
    state.wp[1][0] = c(0.05, -0.02);
    let e = state.constants.chi_p_ev + 1.2 * state.constants.rydberg_ev;
    let out = he_p_bf_source(e, &state, PBoundFreeTable::jacobs_high_length()).unwrap();
    let lhs = out.atomic_b.trace().re;
    let rhs = -out.event_rate_density;
    assert!((lhs - rhs).abs() <= 1e-10 * (1.0 + lhs.abs() + rhs.abs()));
}
